before:
public class Greeting {
    public static String hello(String name) {
        return "Hello, " + name + "!";
    }
}

after:
public class Greeting {
    public static String hello(String greeting, String name) {
        return greeting + ", " + name + "!";
    }
}

test:
public class Test {
    public static void main(String[] a) {
        if (!(Greeting.hello("Hi", "Bo").equals("Hi, Bo!"))) throw new AssertionError("custom greeting");
        if (!(Greeting.hello("Hello", "Ann").equals("Hello, Ann!"))) throw new AssertionError("hello");
        System.out.println("PASS");
    }
}
